import sys
import re
import json
from datetime import datetime

def analyze_logs(filepath):
    total_valid = 0
    total_malformed = 0
    # Structure: {service: {level: count}}
    by_service = {}

    # Regex breakdown:
    # ^(?P<ts>\S+) : Timestamp (non-whitespace)
    # \s+svc=(?P<svc>[^\s]+) : svc=...
    # \s+lvl=(?P<lvl>DEBUG|INFO|WARN|ERROR) : lvl=...
    # (?:\s+status=(?P<status>\d+)\s+latency_ms=(?P<latency>\d+))? : Optional status/latency
    # \s+msg="(?P<msg>.*)"$ : msg="..." at end of line
    pattern = re.compile(
        r'^(?P<ts>\S+)\s+svc=(?P<svc>[^\s]+)\s+lvl=(?P<lvl>DEBUG|INFO|WARN|ERROR)'
        r'(?:\s+status=(?P<status>\d+)\s+latency_ms=(?P<latency>\d+))?'
        r'\s+msg="(?P<msg>.*)"$'
    )

    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip('\n')
                if not line.strip():
                    continue

                match = pattern.match(line)
                is_valid = True

                if not match:
                    is_valid = False
                else:
                    # Validate Timestamp
                    ts_str = match.group('ts')
                    try:
                        datetime.strptime(ts_str, '%Y-%m-%dT%H:%M:%SZ')
                    except ValueError:
                        is_valid = False

                if is_valid:
                    total_valid += 1
                    svc = match.group('svc')
                    lvl = match.group('lvl')

                    if svc not in by_service:
                        by_service[svc] = {}
                    by_service[svc][lvl] = by_service[svc].get(lvl, 0) + 1
                else:
                    total_malformed += 1

    except FileNotFoundError:
        # If file doesn't exist, we treat it as 0 lines processed
        pass

    result = {
        "total": total_valid,
        "malformed": total_malformed,
        "by_service": by_service
    }
    return result

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(0)

    output = analyze_logs(sys.argv[1])
    print(json.dumps(output))
