import sys
import json
from datetime import datetime, timezone

def main():
    if len(sys.argv) != 4:
        return

    log_file = sys.argv[1]
    try:
        window_seconds = int(sys.argv[2])
        threshold = float(sys.argv[3])
    except ValueError:
        return

    valid_levels = {"DEBUG", "INFO", "WARN", "ERROR"}
    # windows maps epoch_start -> {'total': int, 'errors': int}
    windows = {}

    try:
        with open(log_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                try:
                    data = json.loads(line)
                except json.JSONDecodeError:
                    continue

                # Validate required fields
                if not all(k in data for k in ("ts", "service", "level", "message")):
                    continue

                if data["level"] not in valid_levels:
                    continue

                # Validate timestamp
                try:
                    # Format: 2026-03-04T10:15:03Z
                    ts_str = data["ts"]
                    dt = datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
                    epoch = int(dt.timestamp())
                except (ValueError, TypeError):
                    continue

                # Only process request lines (those with status)
                if "status" in data:
                    status = data["status"]
                    window_start_epoch = (epoch // window_seconds) * window_seconds

                    if window_start_epoch not in windows:
                        windows[window_start_epoch] = {"total": 0, "errors": 0}

                    windows[window_start_epoch]["total"] += 1
                    if status >= 500:
                        windows[window_start_epoch]["errors"] += 1

    except FileNotFoundError:
        return

    sorted_starts = sorted(windows.keys())
    output_windows = []
    alerts = []

    for start_epoch in sorted_starts:
        stats = windows[start_epoch]
        start_dt = datetime.fromtimestamp(start_epoch, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

        total = stats["total"]
        errors = stats["errors"]
        error_rate = errors / total if total > 0 else 0.0

        # Round error_rate to 4 decimals for the JSON output
        rounded_rate = round(error_rate, 4)

        output_windows.append({
            "start": start_dt,
            "total": total,
            "errors": errors,
            "error_rate": rounded_rate
        })

        # Alert if unrounded error rate is strictly greater than threshold
        if error_rate > threshold:
            alerts.append(start_dt)

    result = {
        "windows": output_windows,
        "alerts": alerts
    }

    print(json.dumps(result))

if __name__ == "__main__":
    main()
