import math
from datetime import datetime

def main():
    if len(sys.argv) < 2:
        return

    log_file = sys.argv[1]
    service_latencies = {}
    valid_levels = {"DEBUG", "INFO", "WARN", "ERROR"}
    ts_format = "%Y-%m-%dT%H:%M:%SZ"

    try:
        with open(log_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                try:
                    data = json.loads(line)

                    # Check required fields
                    required = ("ts", "service", "level", "message")
                    if not all(k in data for k in required):
                        continue

                    # Validate level
                    if data["level"] not in valid_levels:
                        continue

                    # Validate timestamp
                    datetime.strptime(data["ts"], ts_format)

                    # Process latency if present
                    if "latency_ms" in data and isinstance(data["latency_ms"], (int, float)):
                        svc = data["service"]
                        if svc not in service_latencies:
                            service_latencies[svc] = []
                        service_latencies[svc].append(int(data["latency_ms"]))

                except (json.JSONDecodeError, ValueError, TypeError):
                    # Skip malformed lines
                    continue
    except FileNotFoundError:
        return

    output_services = {}

    for svc, latencies in service_latencies.items():
        if not latencies:
            continue

        latencies.sort()
        n = len(latencies)

        def get_percentile(p):
            # Nearest-rank method: rank = ceil(p * n / 100)
            # Using integer arithmetic for ceil(a/b) -> (a + b - 1) // b
            # rank = (p * n + 99) // 100
            # However, the spec says: rank = ceil(p*n/100)
            # In Python, math.ceil(p * n / 100) is the most direct implementation.
            rank = math.ceil((p * n) / 100)
            # Ensure rank is at least 1 and does not exceed n
            idx = max(1, min(rank, n)) - 1
            return latencies[idx]

        output_services[svc] = {
            "n": n,
            "p50": get_percentile(50),
            "p95": get_percentile(95),
            "p99": get_percentile(99)
        }

    result = {"services": output_services}
    print(json.dumps(result))

if __name__ == "__main__":
    main()
