from datetime import datetime

def main():
    if len(sys.argv) < 2:
        return

    log_file = sys.argv[1]
    services_data = {}
    valid_levels = {"DEBUG", "INFO", "WARN", "ERROR"}

    try:
        with open(log_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                parts = line.split(None, 5)
                if len(parts) < 5:
                    continue

                ts_str, service, level, status, latency_str = parts[0], parts[1], parts[2], parts[3], parts[4]

                # Validate Timestamp
                try:
                    datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%SZ")
                except ValueError:
                    continue

                # Validate Level
                if level not in valid_levels:
                    continue

                # Validate Status and Latency
                # Status must be '-' or digits
                if status != '-' and not status.isdigit():
                    continue

                # Latency must be '-' or digits
                if latency_str != '-' and not latency_str.isdigit():
                    continue

                # Process Latency
                if latency_str != '-':
                    latency_val = int(latency_str)
                    if service not in services_data:
                        services_data[service] = []
                    services_data[service].append(latency_val)

    except FileNotFoundError:
        return

    output = {"services": {}}

    for service, latencies in services_data.items():
        if not latencies:
            continue

        latencies.sort()
        n = len(latencies)

        def get_percentile(p, n, sorted_list):
            # nearest-rank method: rank = ceil(p * n / 100)
            # Using integer arithmetic for ceil(a/b): (a + b - 1) // b
            # Here: ceil( (p * n) / 100 ) -> (p * n + 99) // 100
            # However, the spec says rank = ceil(p*n/100)
            # Let's use math.ceil for precision with floats as per standard formula
            rank = math.ceil((p * n) / 100.0)
            # rank is 1-based, list is 0-based
            return sorted_list[rank - 1]

        output["services"][service] = {
            "n": n,
            "p50": get_percentile(50, n, latencies),
            "p95": get_percentile(95, n, latencies),
            "p99": get_percentile(99, n, latencies)
        }

    print(json.dumps(output))

if __name__ == "__main__":
